import torch # Preserve automatic differentiation through all native material-state consistency equations.
def symmetric_tensor(components): # Convert native xx,yy,zz,xy,xz,yz tensor components without engineering-shear factors.
    xx,yy,zz,xy,xz,yz=components.unbind(-1);return torch.stack((torch.stack((xx,xy,xz),-1),torch.stack((xy,yy,yz),-1),torch.stack((xz,yz,zz),-1)),-2) # Stack operations retain gradients for every tensor component.
def tensor_components(tensor): # Return the exact six-component native ordering for reconstructed stress labels.
    return torch.stack((tensor[...,0,0],tensor[...,1,1],tensor[...,2,2],tensor[...,0,1],tensor[...,0,2],tensor[...,1,2]),-1) # Keep tensor shear components unscaled.
def deviator(tensor): # Remove the physical three-dimensional trace in the current spatial frame.
    identity=torch.eye(3,dtype=tensor.dtype,device=tensor.device);trace=tensor.diagonal(dim1=-2,dim2=-1).sum(-1);return tensor-trace[...,None,None]*identity/3. # Use the full tensor trace rather than a vector-component average.
def hardening_curve(peeq,yield_stress): # Reproduce the actual two-point native kinematic curve with its terminal plateau.
    ordinate=yield_stress+1500.*peeq.clamp(0.,.05);derivative=torch.where((peeq>0.)&(peeq<.05),torch.full_like(peeq,1500.),torch.zeros_like(peeq));return ordinate,derivative # The ordinate is not the radius of the kinematic yield surface; its initial ordinate sets that radius.
def steel_response(F,raw_plastic_metric,raw_material_backstress,young=200000.,poisson=.3): # Reconstruct the pinned finite-strain steel stress from the complete endpoint plastic metric.
    metric=symmetric_tensor(raw_plastic_metric);backstress=symmetric_tensor(raw_material_backstress);identity=torch.eye(3,dtype=F.dtype,device=F.device);cp_inverse=identity-2.*metric;J=torch.linalg.det(F);safe_J=J.clamp_min(1.e-8) # Raw SDV2:7=(I-Cp_inverse)/2; retain actual J while extending arithmetic below zero only to produce a finite optimization barrier.
    mu=young/(2.*(1.+poisson));bulk=young/(3.*(1.-2.*poisson));bbar=(F@cp_inverse@F.transpose(-1,-2))*safe_J[...,None,None].pow(-2./3.);sigma=(.5*bulk*(J.square()-1.)[...,None,None]*identity+mu*deviator(bbar))/safe_J[...,None,None] # This is algebraically the current-Cp form of native incplas.f stress lines330–339 and771–790 with zero residual stress.
    spatial_backstress=deviator(F@backstress@F.transpose(-1,-2))*safe_J[...,None,None].pow(-5./3.) # Native SDV8:13 is a reference-frame tensor; push forward and divide Kirchhoff backstress by J before comparing to Cauchy stress.
    return {'sigma':sigma,'sigma_components':tensor_components(sigma),'spatial_backstress':spatial_backstress,'cp_inverse':cp_inverse,'det_F':J,'orientation_barrier':torch.relu(1.e-6-J).square()} # No state projection, eigenvalue clipping or replacement of the predicted plastic tensor is performed.
def endpoint_constraints(F,stress,peeq,raw_plastic_metric,raw_material_backstress,yield_stress,previous_peeq=None,previous_plastic_metric=None,previous_material_backstress=None): # Return differentiable full-point material constraints; leading dimensions may contain time, elements and integration points.
    response=steel_response(F,raw_plastic_metric,raw_material_backstress);sigma=symmetric_tensor(stress);scale=torch.as_tensor(yield_stress,dtype=F.dtype,device=F.device);closure=(sigma-response['sigma'])/scale;radius=(deviator(sigma)-response['spatial_backstress']).square().sum((-2,-1)).clamp_min(1.e-24).sqrt()*(1.5**.5);ordinate,derivative=hardening_curve(peeq,scale) # Keep the fixed initial yield radius distinct from the separately saturating kinematic hardening curve.
    losses={'steel_stress_closure':closure.square().mean(),'orientation_barrier':response['orientation_barrier'].mean()};diagnostics={'stress_closure_tensor':closure,'yield_excess_MPa':radius-scale,'yield_radius_MPa':radius,'kinematic_curve_ordinate_MPa':ordinate,'kinematic_curve_derivative_MPa':derivative,'det_F':response['det_F'],'cp_inverse':response['cp_inverse'],'reconstructed_sigma':response['sigma'],'spatial_backstress':response['spatial_backstress']} # Yield excess is a measured diagnostic, not a falsely exact zero constraint across a native hardening-knot increment.
    if previous_peeq is not None: # Enable complete endpoint-history necessary conditions when the immediately preceding saved state is supplied.
        assert previous_plastic_metric is not None and previous_material_backstress is not None;increment=peeq-previous_peeq;delta_metric=raw_plastic_metric-previous_plastic_metric;delta_backstress=raw_material_backstress-previous_material_backstress;plateau=previous_peeq>=.0500001;elastic=increment.abs()<=1.e-10 # Exclude the rounded knot itself; endpoints after the knot must retain the native material-frame backstress exactly.
        plateau_count=plateau.sum().clamp_min(1);elastic_count=elastic.sum().clamp_min(1);losses['plateau_backstress_constancy']=((delta_backstress/scale).square()*plateau[...,None]).sum()/(6.*plateau_count);losses['elastic_metric_constancy']=(delta_metric.square()*elastic[...,None]).sum()/(6.*elastic_count);losses['elastic_backstress_constancy']=((delta_backstress/scale).square()*elastic[...,None]).sum()/(6.*elastic_count) # These necessary implications do not reconstruct missing adaptive substeps or assert a complete J2 return map.
        diagnostics.update({'peeq_increment':increment,'plateau_mask':plateau,'elastic_endpoint_mask':elastic,'material_backstress_increment':delta_backstress,'raw_metric_increment':delta_metric}) # Expose masks and raw increments so numerical audits cannot hide an empty activation set.
    return {'losses':losses,'diagnostics':diagnostics,'scope':'Pinned finite-strain elastic stress closure from the complete plastic metric; correctly pushed-forward native backstress; exact post-plateau/zero-plastic-increment necessary history conditions. Not a reconstruction of adaptive native J2 increments.'} # Keep explicit limitations beside the executable training interface.
def closure_losses(Fsteel,state_steel,previous_state_steel=None,params=None): # Match the whole-graph physics adapter with flattened steel IPs and the unchanged twenty-four-channel state schema.
    assert params is not None;history={} if previous_state_steel is None else {'previous_peeq':previous_state_steel[...,9],'previous_plastic_metric':previous_state_steel[...,10:16],'previous_material_backstress':previous_state_steel[...,16:22]} # Read only the supplied predicted state and declared material parameters, never reference response labels.
    return endpoint_constraints(Fsteel,state_steel[...,3:9],state_steel[...,9],state_steel[...,10:16],state_steel[...,16:22],params[1],**history) # Preserve input float32 or float64, device and automatic differentiation without hidden dtype conversions or state correction.
def concrete_response(F,young=32000.,poisson=.2): # Reconstruct the actual linear-elastic material in NLGEOM using its Green strain and second Piola stress.
    identity=torch.eye(3,dtype=F.dtype,device=F.device);green=.5*(F.transpose(-1,-2)@F-identity);mu=young/(2.*(1.+poisson));lam=young*poisson/((1.+poisson)*(1.-2.*poisson));second_piola=lam*green.diagonal(dim1=-2,dim2=-1).sum(-1)[...,None,None]*identity+2.*mu*green;J=torch.linalg.det(F);sigma=(F@second_piola@F.transpose(-1,-2))/J.clamp_min(1.e-8)[...,None,None] # Native calctotstrain.f, linel.f and resultsmech.f together implement this St Venant–Kirchhoff finite-strain response.
    return {'sigma':sigma,'sigma_components':tensor_components(sigma),'det_F':J,'green_strain':green,'second_piola':second_piola} # No cracking, damage or plastic strain is introduced into the declared elastic concrete material.
def concrete_closure_losses(Fconcrete,state_concrete,stress_scale=1.): # Supply the same differentiable endpoint closure API for every concrete integration point.
    response=concrete_response(Fconcrete);residual=(symmetric_tensor(state_concrete[...,3:9])-response['sigma'])/stress_scale;return {'losses':{'concrete_stress_closure':residual.square().mean()},'diagnostics':{'stress_closure_tensor':residual,'reconstructed_sigma':response['sigma'],'det_F':response['det_F']},'scope':'Native isotropic elastic concrete with NLGEOM: St Venant–Kirchhoff Green-strain/second-Piola law pushed to Cauchy stress.'} # Let the whole-graph owner choose a declared input-only physical stress scale without using hidden reference outputs.
